// Service worker for offline play. It stores nothing on its own: the
// landing page's Cache link (common/offline.js) sends "cache", which fetches
// every file in FILES and replaces the stored copy. Requests go to the
// network; when that fails they are answered from the stored copy.
const CACHE = "abstract-games";

// BEGIN FILES (generated by .tools/scripts/offline_files.mjs)
