const urlOf = (file) => new URL(file, location).href;

// Fetch every file, then replace the stored copy. If any file fails, the old
// copy is kept.
async function cacheAll() {
  const responses = await Promise.all(FILES.map(async (file) => {
    const res = await fetch(urlOf(file), { cache: "no-cache" });
    if (!res.ok) throw new Error(`${file}: ${res.status}`);
    return [urlOf(file), res];
  }));
  await caches.delete(CACHE);
  const cache = await caches.open(CACHE);
  await Promise.all(responses.map(([url, res]) => cache.put(url, res)));
  return responses.length;
}

self.addEventListener("install", () => self.skipWaiting());
self.addEventListener("activate", (event) => event.waitUntil(self.clients.claim()));

self.addEventListener("message", (event) => {
  if (event.data !== "cache") return;
  const [port] = event.ports;
  event.waitUntil(cacheAll().then(
    (count) => port.postMessage({ ok: true, count }),
    (err) => port.postMessage({ ok: false, error: String(err) })));
});

// The stored copy of a request: directory URLs are their index.html, and the
// query is ignored.
function fromCache(request) {
  const url = new URL(request.url);
  if (url.pathname.endsWith("/")) url.pathname += "index.html";
  return caches.match(url.href, { ignoreSearch: true })
    .then((res) => res || Response.error());
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET" || new URL(request.url).origin !== location.origin) return;
  event.respondWith(fetch(request).catch(() => fromCache(request)));
});
